solutionCodeJson.code:
// Little's law: L = lambda * W (requests in flight = throughput * latency).
function concurrency(lambda, seconds) {
  return Math.round(lambda * seconds * 1e6) / 1e6;
}
// Pool size for a mix of waiting (I/O) and computing: cores * (1 + wait / compute), rounded up.
function poolSize(cores, waitMs, computeMs) {
  return Math.ceil(cores * (1 + waitMs / computeMs));
}
